def values(self, *keys):
    """ Return the values of the record, optionally filtering to
    include only certain values by index or key.

    :param keys: indexes or keys of the items to include; if none
                 are provided, all values will be included
    :return: list of values
    :rtype: list
    """
    # Helper to get all values
    def _all_values():
        if hasattr(self, "_items"):
            return [v for _, v in self._items]
        if hasattr(self, "items"):
            return [v for _, v in self.items()]
        raise AttributeError("Object has no items to iterate over")

    # If no keys specified, return all values
    if not keys:
        return _all_values()

    # Collect values based on provided keys (index or key)
    result = []
    if hasattr(self, "_items"):
        for idx, (k, v) in enumerate(self._items):
            for key in keys:
                if isinstance(key, int) and key == idx:
                    result.append(v)
                elif key == k:
                    result.append(v)
    elif hasattr(self, "items"):
        for k, v in self.items():
            for key in keys:
                if key == k:
                    result.append(v)
    else:
        raise AttributeError("Object has no items to iterate over")

    return result

