def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass. """
    # Validate the fields argument
    if not isinstance(fields, (list, tuple)):
        raise TypeError("fields must be a list or tuple of field names")
    for f in fields:
        if not isinstance(f, str) or not f.isidentifier():
            raise ValueError(f"Invalid field name: {f!r}")

    # Build the namespace for the new class
    namespace = {
        "__slots__": tuple(fields),
        "SRID_MAP": srid_map,
    }

    # Define an __init__ that accepts the fields as positional or keyword arguments
    def __init__(self, *args, **kwargs):
        if len(args) > len(fields):
            raise TypeError(f"Expected at most {len(fields)} positional arguments, got {len(args)}")
        # Assign positional arguments
        for name, value in zip(fields, args):
            setattr(self, name, value)
        # Assign remaining fields from keyword arguments or default to None
        for name in fields[len(args):]:
            if name in kwargs:
                setattr(self, name, kwargs.pop(name))
            else:
                setattr(self, name, None)
        if kwargs:
            unexpected = ", ".join(kwargs)
            raise TypeError(f"Unexpected keyword arguments: {unexpected}")

    namespace["__init__"] = __init__

    # Create and return the new subclass of Point
    return type(name, (Point,), namespace)

