def parse_version(s: str) -> tuple[int, ...]:
    """poor man's version comparison

    Splits the input string on dots and converts each component to an integer.
    Non‑numeric suffixes are ignored (e.g. ``1.2.3-alpha`` becomes ``(1, 2, 3)``).
    If a component cannot be parsed as an integer, it is treated as zero.
    """
    parts: list[int] = []
    for part in s.split('.'):
        try:
            parts.append(int(part))
        except ValueError:
            # Extract leading digits if any
            num = ''
            for ch in part:
                if ch.isdigit():
                    num += ch
                else:
                    break
            parts.append(int(num) if num else 0)
    return tuple(parts)

