def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    result = []
    seen = set()
    for cls in classes:
        if cls in seen:
            continue
        # Skip if this class is a superclass of any other in the list
        if any(issubclass(other, cls) for other in classes if other is not cls):
            continue
        result.append(cls)
        seen.add(cls)
    return result

