def validate(self, path):
    """Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    try:
        if not path:
            return False
        if not os.path.isdir(path):
            return False

        # Check for the required .ocfl_version file
        version_file = os.path.join(path, ".ocfl_version")
        if not os.path.isfile(version_file):
            return False

        # Ensure the .ocfl_version file contains a valid integer
        with open(version_file, "r") as f:
            content = f.read().strip()
        if not content.isdigit():
            return False

        # Optional: validate .ocfl_root if present
        root_file = os.path.join(path, ".ocfl_root")
        if os.path.isfile(root_file):
            with open(root_file, "r") as f:
                root_path = f.read().strip()
            if not root_path:
                return False
            full_root = os.path.join(path, root_path)
            if not os.path.isdir(full_root):
                return False

        return True
    except Exception:
        return False

