def validate_as_prior_version(self, prior):
    """Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    # Ensure prior is the same type
    if not isinstance(prior, type(self)):
        raise TypeError('prior must be an instance of the same validator class')

    # Ensure both inventories expose a version attribute
    if not hasattr(self, 'inventory_version') or not hasattr(prior, 'inventory_version'):
        raise AttributeError('Both inventories must have an inventory_version attribute')

    # Prior must be older than the current inventory
    if prior.inventory_version >= self.inventory_version:
        raise ValueError(
            f'prior inventory version ({prior.inventory_version}) must be older than current version ({self.inventory_version})'
        )

    # Attributes that should match between the two inventories
    attrs_to_check = [
        'species',
        'parameters',
        'stoichiometry_matrix',
        'propensities',
        'constraints',
    ]

    for attr in attrs_to_check:
        if hasattr(self, attr) and hasattr(prior, attr):
            if getattr(self, attr) != getattr(prior, attr):
                raise ValueError(
                    f'Attribute "{attr}" differs between current and prior inventories'
                )

    # If all checks pass, the prior is considered valid
    return True

