def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    result = {}

    # Case 1: inventory is a dict mapping logical_path -> data
    if isinstance(inventory, dict):
        for logical_path, data in inventory.items():
            # data could be a dict mapping version -> content(s)
            if isinstance(data, dict):
                content = data.get(version)
                if content is not None:
                    if isinstance(content, (list, set, tuple)):
                        result[logical_path] = set(content)
                    else:
                        result[logical_path] = {content}
            # data could be a list of (ver, content) tuples
            elif isinstance(data, (list, tuple)):
                for entry in data:
                    if isinstance(entry, (list, tuple)) and len(entry) >= 2:
                        ver, content = entry[0], entry[1]
                        if ver == version:
                            result.setdefault(logical_path, set()).add(content)

    # Case 2: inventory is a list of entries
    elif isinstance(inventory, (list, tuple)):
        for entry in inventory:
            # entry could be a tuple (logical_path, ver, content)
            if isinstance(entry, (list, tuple)) and len(entry) >= 3:
                logical_path, ver, content = entry[0], entry[1], entry[2]
                if ver == version:
                    result.setdefault(logical_path, set()).add(content)
            # entry could be a dict with keys 'logical_path', 'version', 'content_file'
            elif isinstance(entry, dict):
                if entry.get('version') == version:
                    logical_path = entry.get('logical_path')
                    content = entry.get('content_file')
                    if logical_path and content:
                        result.setdefault(logical_path, set()).add(content)

    return result

