                env=env,
                stdout=subprocess.PIPE,
                stderr=stderr,
                text=True
            )
            if result.returncode != 0:
                raise subprocess.CalledProcessError(
                    result.returncode, cmd, output=result.stdout, stderr=result.stderr
                )
            outputs.append(result.stdout)
        return outputs

