def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    # Retrieve all objects in the hierarchy.  The concrete implementation
    # may expose them via an attribute named ``_objects`` or a method
    # ``_get_all_objects``.  We fall back to an empty list if neither is
    # available.
    if hasattr(self, "_get_all_objects") and callable(self._get_all_objects):
        objects = self._get_all_objects()
    else:
        objects = getattr(self, "_objects", [])

    num_objects = 0
    good_objects = 0

    for obj in objects:
        num_objects += 1
        is_valid = True

        if validate_objects:
            try:
                # Assume each object implements a ``validate`` method that
                # raises an exception on failure.
                obj.validate()
            except Exception as exc:
                is_valid = False
                if show_warnings:
                    print(f"[validate_hierarchy] Validation failed for {obj!r}: {exc}")

        if check_digests:
            try:
                # Assume each object implements a ``check_digest`` method
                # that raises an exception on mismatch.
                obj.check_digest()
            except Exception as exc:
                is_valid = False
                if show_warnings:
                    print(f"[validate_hierarchy] Digest check failed for {obj!r}: {exc}")

        if is_valid:
            good_objects += 1

    return num_objects, good_objects

