def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    # Ensure we have a root inventory to compare against
    if not hasattr(self, "root_inventory") or not isinstance(self.root_inventory, dict):
        raise ValueError("root_inventory must be a dict of file digests")
    # Prepare a place to record digest differences
    self.different_digests = {}
    # Iterate over each version directory in order
    for vdir in version_dirs:
        # Build the path to the inventory file for this version
        inv_path = os.path.join(self.inventory_dir, vdir, "inventory.json")
        if not os.path.exists(inv_path):
            raise ValueError(f"Missing inventory for version directory '{vdir}'")
        # Load the inventory
        with open(inv_path, "r", encoding="utf-8") as fh:
            try:
                inv = json.load(fh)
            except Exception as exc:
                raise ValueError(f"Failed to parse inventory at '{inv_path}': {exc}")
        if not isinstance(inv, dict):
            raise ValueError(f"Inventory at '{inv_path}' must be a mapping of file paths to digests")
        # Verify that every file in the root inventory is present in this version's inventory
        for file_path, root_digest in self.root_inventory.items():
            if file_path not in inv:
                raise ValueError(f"File '{file_path}' missing from inventory of version '{vdir}'")
            # Compare digests and record any differences
            if inv[file_path] != root_digest:
                self.different_digests.setdefault(file_path, []).append(vdir)
    return self

