def unquote(name):
    """Remove quote from the given name."""
    if not isinstance(name, str):
        return name
    # If the string starts and ends with the same quote character, strip them
    if len(name) >= 2 and name[0] == name[-1] and name[0] in ('"', "'", "`"):
        return name[1:-1]
    # Otherwise, remove all quote characters from the string
    return re.sub(r"[\"'`]", "", name)

