def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    # Determine platform if needed
    if platform == 'this':
        import sys
        platform = 0 if sys.platform.startswith('win') else 1

    # POSIX: use a regex that respects single and double quotes
    if platform == 1:
        # Matches either a double-quoted string, a single-quoted string, or a non-space token
        pattern = re.compile(r'''(?:"([^"]*)"|'([^']*)'|(\S+))''')
        args = []
        for m in pattern.finditer(s):
            if m.group(1) is not None:
                args.append(m.group(1))
            elif m.group(2) is not None:
                args.append(m.group(2))
            else:
                args.append(m.group(3))
        return args

    # Windows: use shlex with posix=False to honor Windows quoting rules
    if platform == 0:
        import shlex
        return shlex.split(s, posix=False)

    # Unsupported platform value
    raise ValueError('Unsupported platform value: %r' % platform)

