def prepare_repository_from_archive(
    archive_path: str,
    filename: Optional[str] = None,
    tmp_path: Union[PosixPath, str] = "/tmp",
) -> str:
    """Given an existing archive_path, uncompress it.
    Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.
    """
    # Determine the destination directory name
    if filename:
        dest_dir_name = filename
    else:
        # Extract base name from the archive path
        base = archive_path.split('/')[-1]
        if base.endswith('.tar.gz'):
            dest_dir_name = base[:-7]
        elif base.endswith('.tar.bz2'):
            dest_dir_name = base[:-8]
        elif base.endswith('.tar'):
            dest_dir_name = base[:-4]
        elif base.endswith('.zip'):
            dest_dir_name = base[:-4]
        else:
            dest_dir_name = base.rsplit('.', 1)[0]

    # Build the full destination directory path
    dest_dir = f"{tmp_path}/{dest_dir_name}"

    # Create the destination directory
    subprocess.run(['mkdir', '-p', dest_dir], check=True)

    # Choose extraction command based on archive type
    if archive_path.endswith('.tar.gz') or archive_path.endswith('.tgz'):
        cmd = ['tar', '-xzf', archive_path, '-C', dest_dir]
    elif archive_path.endswith('.tar.bz2') or archive_path.endswith('.tbz2'):
        cmd = ['tar', '-xjf', archive_path, '-C', dest_dir]
    elif archive_path.endswith('.tar'):
        cmd = ['tar', '-xf', archive_path, '-C', dest_dir]
    elif archive_path.endswith('.zip'):
        cmd = ['unzip', '-q', archive_path, '-d', dest_dir]
    else:
        raise ValueError(f"Unsupported archive type: {archive_path}")

    # Perform extraction
    subprocess.run(cmd, check=True)

    # Return the file URL for the extracted repository
    return f"file://{dest_dir}"

