def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    # Determine whether candidate is a class or an instance
    cls = candidate if isinstance(candidate, type) else candidate.__class__

    # Basic subclass check
    if not issubclass(cls, iface):
        raise TypeError(f"{cls.__name__} does not subclass {iface.__name__}")

    # Check abstract methods (if any)
    abstract_methods = getattr(iface, "__abstractmethods__", set())
    missing_abstract = [name for name in abstract_methods if not hasattr(cls, name)]
    if missing_abstract:
        if tentative:
            # In tentative mode we simply note the missing abstract methods
            pass
        else:
            raise TypeError(
                f"{cls.__name__} is missing abstract methods: "
                f"{', '.join(missing_abstract)}"
            )

    # Verify that all public attributes/methods of iface are present in candidate
    for name in dir(iface):
        if name.startswith("_"):
            continue  # skip private and special attributes
        if not hasattr(cls, name):
            if tentative:
                continue
            raise TypeError(
                f"{cls.__name__} is missing attribute '{name}' required by {iface.__name__}"
            )
        # If the attribute is a method in iface, ensure candidate's attribute is callable
        iface_attr = getattr(iface, name)
        candidate_attr = getattr(cls, name)
        if callable(iface_attr) and not callable(candidate_attr):
            raise TypeError(
                f"Attribute '{name}' in {cls.__name__} should be callable as defined in {iface.__name__}"
