def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    # If an explicit metaclass was supplied, use it
    if explicit_mc is not None:
        return explicit_mc

    # No bases: default to the built‑in type
    if not bases:
        return type

    # Collect the metaclasses of all bases
    mcs = [type(b) for b in bases]

    # Find the most derived metaclass that is a subclass of all others
    result = mcs[0]
    for mc in mcs[1:]:
        if issubclass(result, mc):
            # current result already dominates mc
            continue
        if issubclass(mc, result):
            # mc dominates current result
            result = mc
        else:
            # No common ancestor: metaclass conflict
            raise TypeError(
                "metaclass conflict: %r and %r are not compatible"
                % (result, mc)
            )
    return result

