def isoparse(self, dt_str):
    """Parse an ISO-8601 datetime string into a :class:`datetime.datetime`.

    Supports a wide range of ISO-8601 date and time formats, including
    ISO week dates and time zone offsets. Unspecified components default
    to their lowest value. Midnight may be represented as ``24:00``.
    """
    import re
    from datetime import datetime, timedelta, date
    from dateutil.tz import tzutc, tzoffset

    # Accept a stream
    if hasattr(dt_str, "read"):
        dt_str = dt_str.read()
    dt_str = dt_str.strip()

    # Split date and time+tz
    if "T" in dt_str:
        date_part, time_tz_part = dt_str.split("T", 1)
    else:
        date_part, time_tz_part = dt_str, ""

    # ---------- Parse date part ----------
    year = month = day = None
    week = weekday = None

    # Year only
    m = re.match(r"^(?P<year>\d{4})$", date_part)
    if m:
        year = int(m.group("year"))
        month, day = 1, 1
    else:
        # Year-month
        m = re.match(r"^(?P<year>\d{4})[-]?(?P<month>\d{2})$", date_part)
        if m:
            year = int(m.group("year"))
            month = int(m.group("month"))
            day = 1
        else:
            # Year-month-day
            m = re.match(r"^(?P<year>\d{4})[-]?(?P<month>\d{2})[-]?(?P<day>\d{2})$", date_part)
            if m:
                year = int(m.group("year"))
                month = int(m.group("month"))
                day = int(m.group("day"))
            else:
                # ISO week without day
                m = re.match(r"^(?P<year>\d{4})[-]?W(?P<week>\d{2})$", date_part)
                if m:
                    year = int(m.group("year"))
                    week = int(m.group("week"))
                    weekday = 1  # default Monday
                else:
                    # ISO week with day
                    m = re.match(r"^(?P<year>\d{4})[-]?W(?P<week>\d{2})[-]?(?P<weekday>\d)$", date_part)
                    if m:
                        year = int(m.group("year"))
                        week = int(m.group("week"))
                        weekday = int(m.group("weekday"))
                    else:
                        raise ValueError(f"Unrecognized date format: {date_part}")

