def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    import json
    import xml.etree.ElementTree as ET

    # Try JSON first
    try:
        data = json.loads(document)
        # Ensure the returned dict has the expected keys
        if isinstance(data, dict):
            return data
    except Exception:
        pass

    # Fallback to XRD (XML) parsing
    try:
        root = ET.fromstring(document)
        # XRD may use a namespace; ignore it if present
        def strip_ns(tag):
            return tag.split('}', 1)[-1] if '}' in tag else tag

        subject_elem = next((e for e in root if strip_ns(e.tag) == 'Subject'), None)
        subject = subject_elem.text if subject_elem is not None else None

        aliases = [a.text for a in root.findall('.//Alias') if a.text]

        links = []
        for link in root.findall('.//Link'):
            link_dict = {}
            # Include attributes
            for attr, val in link.attrib.items():
                link_dict[attr] = val
            # Include text content if present
            if link.text and link.text.strip():
                link_dict['text'] = link.text.strip()
            links.append(link_dict)

        return {"subject": subject, "aliases": aliases, "links": links}
    except Exception:
        # If parsing fails, return an empty dict
        return {}

