def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    # Retrieve the mapping of argument names to their maximum allowed lengths.
    # This mapping should be defined on the instance as `arg_lengths`.
    arg_lengths = getattr(self, 'arg_lengths', {})
    for arg_name, value in args.items():
        # Skip arguments that have no length restriction.
        if arg_name not in arg_lengths:
            continue

        max_len = arg_lengths[arg_name]
        if not isinstance(max_len, int):
            raise TypeError(
                f"Maximum length for argument '{arg_name}' must be an integer, "
                f"got {type(max_len).__name__}"
            )
        if max_len < 0:
            raise ValueError(
                f"Maximum length for argument '{arg_name}' must be non‑negative, "
                f"got {max_len}"
            )

        # Only sequences (strings, lists, tuples, dicts) have a length.
        if isinstance(value, (str, list, tuple, dict)):
            if len(value) > max_len:
                raise ValueError(
                    f"Argument '{arg_name}' length {len(value)} exceeds "
                    f"maximum allowed {max_len}"
                )
        else:
            # For non‑sequence values, no length check is performed.
            continue

