    # Iterate over each provided argument
    for arg_name, value in args.items():
        # Retrieve the argument definition (if any)
        arg_def = getattr(self, "arg_definitions", {}).get(arg_name)
        if not arg_def:
            # No definition found – skip validation for this argument
            continue

        # If the argument has a 'choices' specification, validate the value
        choices = arg_def.get("choices")
        if choices is None:
