        # Support both single values and iterable values (e.g., list of choices)
        if isinstance(value, (list, tuple, set)):
            invalid = [v for v in value if v not in choices]
            if invalid:
                raise ValueError(
                    f"Invalid value(s) for argument '{arg_name}': {invalid}. "
                    f"Expected one of {choices}"
                )
        else:
            if value not in choices:
                raise ValueError(
                    f"Invalid value for argument '{arg_name}': {value}. "
                    f"Expected one of {choices}"
                )

