def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    # Ensure args is iterable
    if not hasattr(args, "__iter__"):
        raise TypeError("args must be an iterable")

    # Retrieve bounds from the instance
    if not hasattr(self, "min") or not hasattr(self, "max"):
        raise AttributeError("Instance must have 'min' and 'max' attributes")
    min_val = self.min
    max_val = self.max

    # Iterate over arguments and validate each value
    for idx, val in enumerate(args if not isinstance(args, dict) else args.values()):
        if val < min_val or val > max_val:
            raise ValueError(
                f"Argument at position {idx} with value {val} is outside the allowed range "
                f"[{min_val}, {max_val}]"
            )
    return args

